import{_ as n,l as i,o as e,c as l,v as r,p as s,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"分代假设与晋升","description":"","frontmatter":{"title":"分代假设与晋升","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/generational-promotion.md","filePath":"cs/generational-promotion.md","lastUpdated":1789023840000}'),m={name:"cs/generational-promotion.md"};function h(u,a,_,g,f,b){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="分代假设与晋升" tabindex="-1">分代假设与晋升 <a class="header-anchor" href="#分代假设与晋升" aria-label="Permalink to &quot;分代假设与晋升&quot;">​</a></h1><div class="epigraph"><p>多数对象朝生夕死。幼代频繁复制，活过几次的晋升到老年代，老年代少扫。写屏障记住老到幼的指针。</p><footer>—— 据 Lieberman and Hewitt, A Real-Time Garbage Collector Based on the Lifetimes of Objects；Ungar；主干[标记清除与分代](/cs/gc-mark-gen) 整理</footer></div><p>上一课<a href="/cs/concurrent-incremental-gc">并发 GC</a> 管停顿形态。主干分代已点名。缺口是<strong>晋升策略</strong>：年龄、survivor 空间、老年代满了 Full GC。本课钉假设与失败模式（晋升失败），bump 分配下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>复制半区若当全堆，长命对象反复搬。分代：Eden + survivor，满了后活对象年龄+1，超阈值进 Old。缺口是<strong>何时晋升</strong>，不是三色证明。</p><p>分代假设对某些负载失败：缓存对象全长命，幼代收集几乎不收，只晋升——吞吐量崩。</p><h3 id="晋升不是「对象变类型」" tabindex="-1">晋升不是「对象变类型」 <a class="header-anchor" href="#晋升不是「对象变类型」" aria-label="Permalink to &quot;晋升不是「对象变类型」&quot;">​</a></h3><p>仍是同一对象，只是区域变。身份（地址）复制式会变，须更新指针。</p><p><span class="marginnote">Lieberman–Hewitt 1983。Ungar scavenging。Appel 简单分代。主干 gc-mark-gen。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Eden bump 分配。Minor GC：Eden+from → to，更新记忆集。年龄表。Old 用标记压缩或 CMS。</p>',11)),(e(),s(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDEN%5B%22Eden%20%E5%88%86%E9%85%8D%22%5D%20--%3E%20MINOR%5B%22Minor%20GC%22%5D%0A%20%20MINOR%20--%3E%20SUR%5B%22Survivor%22%5D%0A%20%20SUR%20--%3E%20TEN%5B%22%E6%99%8B%E5%8D%87%20Old%22%5D%0A%20%20TEN%20--%3E%20FULL%5B%22Old%20%E6%BB%A1%E5%88%99%20Full%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与逃逸：未逃逸不进 Eden，减 minor 压力。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>晋升失败：Old 不够，退化 Full，停顿尖峰。并行 scavenge。不要把所有大对象直接 Old 当唯一策略而不测。</p><p>弱引用在分代下要特殊队列，后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 TLAB。后课默认：幼代复制+晋升。下一课 bump 分配与 TLAB。</p><p>也不把分代当人口统计学课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分代假设：新对象易死；晋升保护长命对象。</li><li>写屏障 + 记忆集使 minor 正确。</li><li>假设失败则 minor 无益。</li><li>出处：Lieberman and Hewitt；Ungar；Jones 手册；主干 gc-mark-gen。</li></ul>',9))])}const A=n(m,[["render",h]]);export{T as __pageData,A as default};
